    "dm-app-001": {"prompt":"\\text{Two people each pick a number uniformly at random from }[0,1]\\text{, }x,y\\text{. Use a double integral to find the expected difference }\\int_0^1\\!\\!\\int_0^1|x-y|\\,dx\\,dy"},
    "dm-app-002": {"prompt":"\\text{(Gabriel's horn) Revolve }y=\\frac1x\\ (x\\ge1)\\text{ about the }x\\text{-axis. The surface area diverges but the volume converges: find the volume}"},
    "dm-app-003": {"prompt":"\\text{A particle has velocity }v(t)=e^{-t}\\sin t\\ (t\\ge0)\\text{. The displacement is }\\int_0^{\\infty}v\\,dt=\\frac12\\text{; the total distance integrates }|v|\\text{: find }\\int_0^{\\infty}e^{-t}|\\sin t|\\,dt"},
    "dm-int-001": {"prompt":"\\text{Integrate by parts once to lower the exponent, then use the Dirichlet integral }\\int_0^{\\infty}\\frac{\\sin x}{x}dx=\\frac{\\pi}{2}\\text{; find }\\int_0^{\\infty}\\frac{\\sin^2 x}{x^2}\\,dx"},
    "dm-int-002": {"prompt":"\\text{Expand }\\ln(1-x)\\text{ as a power series and integrate term by term; prove and find }\\int_0^1\\ln x\\ln(1-x)\\,dx"},
    "dm-int-003": {"prompt":"\\text{Integrate by parts to get }\\int_0^{\\pi/2}\\ln\\sin x\\,dx\\text{, then find }\\int_0^{\\pi/2}\\frac{x}{\\tan x}\\,dx"},
    "dm-int-004": {"prompt":"\\text{Substitute }x=e^{-u}\\text{ to turn it into a Gamma-type integral; find }\\int_0^1\\frac{(\\ln x)^2}{1+x^2}\\,dx"},
    "dm-int-005": {"prompt":"\\text{(Area under the softplus curve) Expand }\\ln(1+e^{-x})\\text{ as }\\sum_{n\\ge1}\\frac{(-1)^{n+1}}{n}e^{-nx}\\text{ and integrate term by term; find }\\int_0^{\\infty}\\ln\\!\\left(1+e^{-x}\\right)dx"},
    "dm-int-006": {"prompt":"\\text{Let }I(t)=\\int_0^{\\infty}e^{-x^2}\\cos(2tx)\\,dx\\,\\text{. First show }I'(t)=-2t\\,I(t)\\text{, then find }I(1)"},
    "dm-int-007": {"prompt":"\\text{(Integral proof of the Basel problem) Expand }\\frac{1}{1-xy}\\text{ as a power series, show the integral equals }\\zeta(2)\\text{, then find }\\int_0^1\\!\\!\\int_0^1\\frac{dx\\,dy}{1-xy}"},
    "dm-int-008": {"prompt":"\\text{View it as an integral over a parameter: }\\int_0^1 x^s ds=\\frac{x-1}{\\ln x}\\text{; swap the order of integration to find }\\int_0^1\\frac{x-1}{\\ln x}\\,dx"},
    "dm-int-009": {"prompt":"\\text{(Laplace integral) Let }I(t)=\\int_0^{\\infty}\\frac{\\cos(tx)}{1+x^2}dx\\,\\text{. First show }I''(t)=I(t)\\ (t>0)\\text{, then find }I(1)"},
    "dm-int-010": {"prompt":"\\text{Use King's property }x\\mapsto\\pi-x\\text{ to remove }x\\text{ from the numerator, then a half-angle substitution; find }\\int_0^{\\pi}\\frac{x}{1+\\sin x}\\,dx"},
    "dm-int-011": {"prompt":"\\text{Substitute }x\\mapsto\\frac1x\\text{ and compare the two halves; find }\\int_0^{\\infty}\\frac{\\ln x}{1+x^2}\\,dx"},
    "dm-int-012": {"prompt":"\\text{(Sophomore's dream) Prove }\\int_0^1 x^{-x}dx=\\sum_{n=1}^{\\infty}n^{-n}\\text{ and find the ratio of the two}"},
    "dm-lim-012": {"prompt":"\\text{Let }F(x)=\\int_x^{\\infty}e^{-t^2}dt\\text{. First show }F(x)=\\frac{e^{-x^2}}{2x}\\left(1+O(x^{-2})\\right)\\text{ by integration by parts, then find }\\lim_{x\\to\\infty}x\\,e^{x^2}F(x)"},
    "dm-seq-001": {"prompt":"\\text{Let }a_1=1,\\ a_{n+1}=a_n+\\frac{1}{a_n}\\text{. First show }a_n\\to\\infty\\text{, then use }a_{n+1}^2=a_n^2+2+\\frac{1}{a_n^2}\\text{ to find }\\lim_{n\\to\\infty}\\frac{a_n}{\\sqrt{n}}"},
    "dm-seq-002": {"prompt":"\\text{Let }x_1=1,\\ x_{n+1}=\\sin x_n\\text{. Given }x_n\\downarrow 0\\text{, use }\\frac{1}{x_{n+1}^2}-\\frac{1}{x_n^2}\\to\\frac13\\text{ and the Stolz theorem to find }\\lim_{n\\to\\infty}\\sqrt{n}\\,x_n"},
    "dm-seq-003": {"prompt":"\\text{Let }f(x)=\\frac{1}{1+x^2}\\text{. Prove }\\lim_{n\\to\\infty}n\\int_0^1 x^n f(x)\\,dx=f(1)\\text{ and find the value of the limit}"},
    "dm-seq-004": {"prompt":"\\text{(Wallis asymptotics) Use the Wallis product or Stirling's formula to show }\\binom{2n}{n}\\sim\\frac{4^n}{\\sqrt{\\pi n}}\\text{, and find }\\lim_{n\\to\\infty}\\sqrt{n}\\,\\binom{2n}{n}\\,4^{-n}"},
    "dm-seq-005": {"prompt":"\\text{Expand }\\sqrt{n^2+n}=n+\\frac12-\\frac{1}{8n}+O(n^{-2})\\text{ and find }\\lim_{n\\to\\infty}\\sin^2\\!\\left(\\pi\\sqrt{n^2+n}\\right)"},
    "dm-seq-006": {"prompt":"\\text{Use the Stolz theorem or a Riemann sum to find }\\lim_{n\\to\\infty}\\frac{\\sqrt{1}+\\sqrt{2}+\\cdots+\\sqrt{n}}{n^{3/2}}"},
    "dm-seq-007": {"prompt":"\\text{Treat the sum as a Riemann sum and find }\\lim_{n\\to\\infty}\\frac{1}{n^2}\\sum_{k=1}^{n}k\\sin\\frac{k}{n}"},
    "dm-seq-008": {"prompt":"\\text{Take logs to get a Riemann sum, then integrate by parts; find }\\lim_{n\\to\\infty}\\prod_{k=1}^{n}\\left(1+\\frac{k^2}{n^2}\\right)^{1/n}"},
    "dm-seq-009": {"prompt":"\\text{Let }I_n=\\int_0^{\\pi/4}\\tan^n x\\,dx\\,\\text{. First establish }I_n+I_{n-2}=\\frac{1}{n-1}\\text{, then find }\\lim_{n\\to\\infty}n\\,I_n"},
    "dm-seq-010": {"prompt":"\\text{Write }n^{1/n}=e^{(\\ln n)/n}\\text{ and find }\\lim_{n\\to\\infty}\\frac{n}{\\ln n}\\left(n^{1/n}-1\\right)"},
    "dm-seq-011": {"prompt":"\\text{Let }S_n=e^{-n}\\sum_{k=0}^{n}\\frac{n^k}{k!}\\text{ (a Poisson probability view). Find }\\lim_{n\\to\\infty}S_n"},
    "dm-ser-001": {"prompt":"\\text{Use the Beta function }\\frac{1}{\\binom{2n}{n}}=(2n+1)\\int_0^1 t^n(1-t)^n\\,dt\\text{ and swap sum and integral; find }\\sum_{n=1}^{\\infty}\\frac{1}{\\binom{2n}{n}}"},
    "dm-ser-002": {"prompt":"\\text{Let }H_n=\\sum_{k=1}^n\\frac1k\\text{. Evaluate the generating function }\\sum_{n=1}^{\\infty}\\frac{H_n}{n}x^n=\\operatorname{Li}_2(x)+\\frac12\\ln^2(1-x)\\text{ at }x=-1\\text{ to find }\\sum_{n=1}^{\\infty}\\frac{(-1)^{n+1}H_n}{n}"},
    "dm-ser-003": {"prompt":"\\text{Use }\\arctan\\frac{1}{2n^2}=\\arctan(2n+1)-\\arctan(2n-1)\\text{ to telescope the sum: }\\sum_{n=1}^{\\infty}\\arctan\\frac{1}{2n^2}"},
    "dm-ser-004": {"prompt":"\\text{Use partial fractions and connect with }\\ln 2=\\sum\\frac{(-1)^{k+1}}{k}\\text{ to find }\\sum_{n=1}^{\\infty}\\frac{1}{n(4n^2-1)}"},
    "dm-ser-005": {"prompt":"\\text{Use partial fractions, expand the square, and combine }\\zeta(2)\\text{ with the Leibniz series to find }\\sum_{n=1}^{\\infty}\\frac{1}{(4n^2-1)^2}"},
    "dm-ser-006": {"prompt":"\\text{Use the Fourier series of }\\cosh x\\text{ on }[-\\pi,\\pi]\\text{ (or the Mittag-Leffler expansion of }\\pi\\cot\\pi z\\text{) to find }\\sum_{n=1}^{\\infty}\\frac{1}{n^2+1}"},
    "dx-bio-001": {"prompt":"\\text{After an oral dose the blood concentration is }C(t)=8\\left(e^{-0.2t}-e^{-0.8t}\\right)\\text{ mg/L.}\\quad\\text{At what hour is the concentration highest?}"},
    "dx-bio-002": {"prompt":"\\text{A population of }P(t)=\\dfrac{9}{1+8e^{-0.4t}}\\text{ thousand.}\\quad\\text{In which year is growth fastest (}P'\\text{ largest)?}"},
    "dx-bio-003": {"prompt":"\\text{Poiseuille's law: blood flow }Q=k\\,r^{4}\\text{, }k=0.02\\text{.}\\quad\\text{When the radius is }r=0.5\\text{ cm and shrinking by }0.01\\text{ cm per minute, the rate of change of the flow (cu cm/min)}"},
