    "lec-17-m4": {"prompt":"\\text{Let }\\,f\\text{ be differentiable with }\\nabla f(P)\\neq\\mathbf{0}\\text{. Which of the following is false?}","canonical":"for every unit vector u, D_u f(P) ≥ 0","distractors":["∇f(P) is perpendicular to the level curve through P","f decreases fastest in the direction −∇f(P)","along a unit vector perpendicular to ∇f(P), the directional derivative is 0"]},
    "lec-17-m5": {"prompt":"\\text{Let }\\,z=f(x,y)\\text{ be differentiable with }\\,x=r\\cos\\theta\\text{, }\\,y=r\\sin\\theta\\text{. Then }\\dfrac{\\partial z}{\\partial r}"},
