    "lec-20-q4b": {"prompt":"\\text{Let }\\mathbf{F}=(-y,x,0)\\text{, and let }\\,S\\text{ be the upper hemisphere }\\,z=\\sqrt{1-x^2-y^2}\\text{ (normal pointing up). Use Stokes' theorem to find }\\iint_S(\\nabla\\times\\mathbf{F})\\cdot d\\mathbf{S}"},
    "lx-app-001": {"prompt":"\\text{A stone drops from a cliff }80\\text{ m high; its height after }t\\text{ seconds is }h(t)=80-4.9t^2\\text{ (m).}\\quad\\text{Find the instantaneous velocity at }t=2\\text{ seconds (m/s, down is negative)}"},
    "lx-app-002": {"prompt":"\\text{A city's population (in ten-thousands) after }t\\text{ years is }\\quad P(t)=\\frac{120t+300}{t+6}\\text{.}\\quad\\text{What does the population approach in the long run (ten-thousands)?}"},
    "lx-app-003": {"prompt":"\\text{An IV delivers a fixed dose each hour; after }t\\text{ hours the blood concentration is }\\quad C(t)=12\\left(1-e^{-0.4t}\\right)\\text{ mg/L.}\\quad\\text{What is the long-run steady concentration?}"},
    "lx-app-004": {"prompt":"\\text{Principal }10000\\text{ at annual rate }5\\%\\text{, compounded }n\\text{ times a year, grows to }10000\\left(1+\\frac{0.05}{n}\\right)^{n}\\text{.}\\quad\\text{With continuous compounding (}n\\to\\infty\\text{), how much after one year?}"},
    "lx-app-005": {"prompt":"\\text{A skydiver's speed is }v(t)=55\\left(1-e^{-0.18t}\\right)\\text{ m/s.}\\quad\\text{What is the terminal speed (m/s)?}"},
    "lx-app-006": {"prompt":"\\text{A capacitor charges with voltage }V(t)=9\\left(1-e^{-t/\\tau}\\right)\\text{ and time constant }\\tau=0.25\\text{ s.}\\quad\\text{What voltage does it approach after charging a long time?}"},
    "lx-app-007": {"prompt":"\\text{A factory's average cost is }\\bar{C}(x)=\\frac{2400+18x}{x}\\text{ dollars per unit.}\\quad\\text{What does the average cost approach for very large output?}"},
    "lx-app-008": {"prompt":"\\text{Learning curve: after }x\\text{ hours of practice the accuracy is }\\quad A(x)=\\frac{95x}{x+12}\\text{ percent.}\\quad\\text{What percentage can it never exceed?}"},
    "lx-app-009": {"prompt":"\\text{A drug is taken once a day; the long-run amount in the body is }\\sum_{k=0}^{n}200\\left(0.7\\right)^{k}\\text{ mg. What does it approach as }\\quad n\\to\\infty\\text{?}"},
    "lx-app-010": {"prompt":"\\text{A regular }n\\text{-gon inscribed in a circle of radius }1\\text{ has area }A_n=\\frac{n}{2}\\sin\\frac{2\\pi}{n}\\text{. What does the area approach as }\\quad n\\to\\infty\\text{?}"},
    "lx-app-011": {"prompt":"\\text{A ball drops from }2\\text{ meters and each bounce reaches }0.6\\text{ of the previous height.}\\quad\\text{How many meters does it travel before stopping?}"},
    "lx-app-012": {"prompt":"\\text{Diluting }1\\text{ liters of brine: each time pour out }\\frac{1}{n}\\text{ and refill with pure water. After }n\\text{ repetitions the concentration is }\\left(1-\\frac{1}{n}\\right)^{n}\\text{ times the original. What multiple is it as }\\quad n\\to\\infty\\text{?}"},
    "lx-con-001": {"prompt":"\\text{Let }f(x)=x^2+a\\ (x\\le 2)\\text{, }f(x)=3x-4\\ (x>2)\\text{.}\\quad\\text{Find the }a\\text{ that makes }f\\text{ continuous at }x=2"},
    "lx-con-002": {"prompt":"\\text{Let }f(x)=\\frac{\\sin 3x}{x}\\ (x\\ne 0)\\text{, }f(0)=c\\text{.}\\quad\\text{Find the }c\\text{ that makes }f\\text{ continuous at }x=0"},
    "lx-con-003": {"prompt":"\\text{Find the }a\\text{ for which }f(x)=\\frac{x^2+ax+6}{x-3}\\text{ has a removable discontinuity at }x=3\\text{ (continuous after filling in one value)}"},
    "lx-con-004": {"prompt":"\\text{Given that }\\lim_{x\\to 2}\\frac{x^2+ax-10}{x-2}\\text{ exists, find }a"},
    "lx-con-005": {"prompt":"\\text{What kind of discontinuity does }f(x)=\\frac{|x-4|}{x-4}\\text{ have at }x=4\\text{?}","canonical":"jump","distractors":["removable","infinite","oscillating"]},
    "lx-con-006": {"prompt":"\\text{Since }f(x)=x^3-4x+1\\text{ is continuous and }f(0)=1>0>f(1)=-2\\text{, the intermediate value theorem gives a root in }(0,1)\\text{.}\\quad\\text{Run one Newton step from }x_0=\\tfrac{1}{2}\\text{: what is }x_1\\text{?}"},
