    "refine-series-008": {"prompt":"\\text{Apply Cauchy condensation to }a_n=\\frac{1}{n^{3/2}}\\text{: }\\sum_{k=0}^{\\infty}2^k a_{2^k}\\text{ is a geometric series. Find its common ratio }r"},
