    "refine-series-010": {"prompt":"\\text{Does }\\sum_{n=3}^{\\infty}\\frac{1}{(\\ln n)^{\\ln\\ln n}}\\text{ converge or diverge?}","canonical":"diverges","distractors":["converges","conditionally convergent","absolutely convergent"]},
    "refine-series-011": {"prompt":"\\text{Given }\\sum_{n=1}^{\\infty}\\frac{(-1)^{n+1}}{n^2}=\\frac{\\pi^2}{12}\\text{. Rearrange it as }1+\\frac19-\\frac14+\\frac1{25}+\\frac1{49}-\\frac1{16}+\\cdots\\text{ (two positive terms, then one negative term). Find the new sum}"},
    "refine-series-012": {"prompt":"\\text{Rearrange the alternating harmonic series as one positive term followed by two negative terms: }1-\\frac12-\\frac14+\\frac13-\\frac16-\\frac18+\\frac15-\\cdots\\text{. Find its sum}"},
    "refine-series-013": {"prompt":"\\text{Rearrange the alternating harmonic series as four positive terms followed by one negative term: }1+\\frac13+\\frac15+\\frac17-\\frac12+\\frac19+\\cdots+\\frac1{15}-\\frac14+\\cdots\\text{. Find its sum}"},
    "refine-series-014": {"prompt":"\\text{Rearrange the Leibniz series }1-\\frac13+\\frac15-\\frac17+\\cdots=\\frac{\\pi}{4}\\text{ as two positive terms followed by one negative term: }1+\\frac15-\\frac13+\\frac19+\\frac1{13}-\\frac17+\\cdots\\text{. Find its sum}"},
    "refine-series-015": {"prompt":"\\sum_{n=1}^{\\infty}\\frac{(-1)^{n+1}}{\\sqrt n}\\text{ converges conditionally. Rearrange it as two positive terms followed by one negative term: }1+\\frac{1}{\\sqrt3}-\\frac{1}{\\sqrt2}+\\frac{1}{\\sqrt5}+\\frac{1}{\\sqrt7}-\\frac{1}{\\sqrt4}+\\cdots\\text{. Does the rearranged series converge or diverge?}","canonical":"diverges","distractors":["converges","conditionally convergent","absolutely convergent"]},
    "refine-series-016": {"prompt":"\\text{Is }\\sum_{n=1}^{\\infty}\\frac{(-1)^n\\,n}{n^3+1}\\text{ absolutely convergent, conditionally convergent, or divergent?}","canonical":"absolutely convergent","distractors":["conditionally convergent","divergent","convergent, but absolute convergence cannot be determined"]},
    "refine-series-017": {"prompt":"\\text{Is }\\sum_{n=2}^{\\infty}\\frac{(-1)^n}{\\ln n}\\text{ absolutely convergent, conditionally convergent, or divergent?}","canonical":"conditionally convergent","distractors":["absolutely convergent","divergent","divergent, since the terms do not tend to 0"]},
    "refine-series-018": {"prompt":"\\text{Find }\\sum_{n=1}^{\\infty}(-1)^{n+1}\\frac{2n+1}{n(n+1)}"},
    "refine-series-019": {"prompt":"\\text{Find }\\prod_{n=2}^{\\infty}\\left(1+\\frac{1}{n^2-1}\\right)"},
