    "refine-series-021": {"prompt":"\\text{Find }\\prod_{n=1}^{\\infty}\\cos\\frac{\\pi}{3\\cdot 2^{n}}"},
    "refine-series-022": {"prompt":"\\text{Find }\\prod_{n=1}^{\\infty}\\left(1+\\frac{1}{n}\\right)^{(-1)^{n+1}}"},
    "refine-series-023": {"prompt":"\\text{Find }\\prod_{n=1}^{\\infty}\\left(1+\\frac{1}{n^3}\\right)"},
    "refine-series-024": {"prompt":"\\text{Find }\\sum_{m=1}^{\\infty}\\sum_{n=1}^{\\infty}\\frac{1}{2^m\\,3^n}"},
    "refine-series-025": {"prompt":"\\text{Find }\\sum_{m=1}^{\\infty}\\sum_{n=1}^{\\infty}\\frac{1}{(m+n)!}"},
    "refine-series-026": {"prompt":"\\text{Find }\\sum_{m=1}^{\\infty}\\sum_{n=1}^{\\infty}\\frac{1}{(m+n)\\,2^{m+n}}"},
    "refine-series-027": {"prompt":"\\text{Find }\\sum_{m=0}^{\\infty}\\sum_{n=0}^{\\infty}\\frac{m!\\,n!}{(m+n+2)!}"},
    "refine-series-028": {"prompt":"\\text{Find }\\sum_{m=1}^{\\infty}\\sum_{n=1}^{\\infty}\\frac{1}{m\\,n\\,(m+n+2)}"},
    "refine-series-029": {"prompt":"\\text{Find }\\sum_{n=1}^{\\infty}\\sum_{k=n}^{\\infty}\\frac{1}{3^k}"},
    "refine-series-030": {"prompt":"\\text{Find }\\sum_{n=2}^{\\infty}\\sum_{k=2}^{\\infty}\\frac{(-1)^n}{k^n}"},
    "refine-series-031": {"prompt":"\\text{Find }\\sum_{n=1}^{\\infty}\\frac{1}{n}\\sum_{k=2}^{\\infty}\\frac{1}{k^{2n}}"},
    "refine-series-032": {"prompt":"\\text{The sequence }a_n=2^n+3^n\\ (n\\ge0)\\text{ has generating function }G(x)=\\sum_{n=0}^{\\infty}a_nx^n\\text{. Find }G\\!\\left(\\frac16\\right)"},
    "refine-series-033": {"prompt":"\\text{The number of ways to make 10 dollars from 1-, 2-, and 5-dollar coins (order ignored) equals the coefficient of }x^{10}\\text{ in the expansion of }\\frac{1}{(1-x)(1-x^2)(1-x^5)}\\text{. Find this coefficient}"},
    "refine-series-034": {"prompt":"\\text{Find }\\sum_{n=0}^{\\infty}\\binom{2n}{n}\\frac{1}{8^n}"},
    "refine-series-035": {"prompt":"C_n=\\frac{1}{n+1}\\binom{2n}{n}\\text{ are the Catalan numbers. Find }\\sum_{n=0}^{\\infty}\\frac{C_n}{5^n}"},
    "refine-series-036": {"prompt":"\\text{Find }\\sum_{n=1}^{\\infty}\\binom{2n}{n}\\frac{1}{n\\,8^n}"},
    "refine-series-037": {"prompt":"a_0=1,\\ a_n=a_{n-1}+2\\ (n\\ge1)\\text{. Let }G(x)=\\sum_{n=0}^{\\infty}a_nx^n\\text{; find }G\\!\\left(\\frac12\\right)"},
    "refine-series-038": {"prompt":"\\text{Fibonacci numbers }F_0=0,\\ F_1=1,\\ F_{n+2}=F_{n+1}+F_n\\text{. Find }\\sum_{n=0}^{\\infty}\\frac{F_n}{3^n}"},
    "refine-series-039": {"prompt":"a_0=0,\\ a_1=1,\\ a_{n+2}=5a_{n+1}-6a_n\\text{. Find }\\sum_{n=0}^{\\infty}\\frac{a_n}{7^n}"},
    "refine-series-040": {"prompt":"a_0=0,\\ a_{n+1}=2a_n+n\\ (n\\ge0)\\text{. Find }\\sum_{n=0}^{\\infty}\\frac{a_n}{3^n}"},
    "refine-series-041": {"prompt":"\\text{Derangement numbers }D_0=1,\\ D_1=0,\\ D_n=(n-1)(D_{n-1}+D_{n-2})\\ (n\\ge2)\\text{. Find }\\sum_{n=0}^{\\infty}\\frac{D_n}{n!\\,2^n}"},
    "refine-series-042": {"prompt":"t_0=1,\\ t_1=1,\\ t_{n+1}=t_n+n\\,t_{n-1}\\ (n\\ge1)\\text{ (the number of involutions). Find }\\sum_{n=0}^{\\infty}\\frac{t_n}{n!}"},
    "refine-series-043": {"prompt":"\\sum_{k=1}^{n}k^3=\\frac{n^4}{4}+\\frac{n^3}{2}+c\\,n^2\\text{ holds for all positive integers }n\\,\\text{. Find }c"},
    "refine-series-044": {"prompt":"\\text{Find }\\lim_{n\\to\\infty}\\left(\\sum_{k=1}^{n}\\ln k-\\left(n+\\frac12\\right)\\ln n+n\\right)"},
    "refine-series-045": {"prompt":"\\text{Find }\\lim_{n\\to\\infty}n^3\\left(\\sum_{k=1}^{n}\\frac{1}{k^2}-\\frac{\\pi^2}{6}+\\frac1n-\\frac{1}{2n^2}\\right)"},
    "refine-series-046": {"prompt":"\\text{Find }\\lim_{n\\to\\infty}n\\left(\\ln(n!)-\\left(n+\\frac12\\right)\\ln n+n-\\frac12\\ln(2\\pi)\\right)"},
    "refine-series-047": {"prompt":"H_n=\\sum_{k=1}^{n}\\frac1k\\text{ and }\\gamma\\text{ is Euler's constant. Find }\\lim_{n\\to\\infty}n^2\\left(H_n-\\ln n-\\gamma-\\frac{1}{2n}\\right)"},
    "refine-series-048": {"prompt":"\\text{Find }\\lim_{n\\to\\infty}\\frac{1}{n^2\\,2^n}\\sum_{k=1}^{n}k^2\\,2^k"},
    "refine-series-049": {"prompt":"\\text{Find }\\lim_{n\\to\\infty}\\frac{1}{n^n}\\sum_{k=1}^{n}k^k"},
    "refine-series-050": {"prompt":"\\text{Find }\\lim_{n\\to\\infty}\\frac{1}{\\sqrt n}\\sum_{k=0}^{n}\\binom{2k}{k}\\frac{1}{4^k}"},
    "refine-series-051": {"prompt":"\\text{Given }\\sum_{k=1}^{n}\\left(\\frac{k}{n}\\right)^n\\to\\frac{e}{e-1}\\text{. Find }\\lim_{n\\to\\infty}n\\left(\\frac{e}{e-1}-\\sum_{k=1}^{n}\\left(\\frac{k}{n}\\right)^n\\right)"},
    "refine-series-052": {"prompt":"\\binom{2n}{n}\\frac{1}{4^n}\\sim\\frac{1}{\\sqrt{\\pi n}}\\text{. Find the next-order correction: }\\lim_{n\\to\\infty}n\\left(\\sqrt{\\pi n}\\,\\binom{2n}{n}\\frac{1}{4^n}-1\\right)"},
    "refine-series-053": {"prompt":"\\text{Harmonic numbers }H_n=\\sum_{k=1}^{n}\\frac1k\\text{. Find }H_5"},
    "refine-series-054": {"prompt":"H_n=\\sum_{k=1}^{n}\\frac1k\\text{. Find }\\lim_{n\\to\\infty}\\left(H_{3n}-H_n\\right)"},
    "refine-series-055": {"prompt":"H_n=\\sum_{k=1}^{n}\\frac1k\\text{. Find }\\sum_{n=1}^{\\infty}\\frac{H_n}{(n+1)(n+2)}"},
    "refine-series-056": {"prompt":"H_n=\\sum_{k=1}^{n}\\frac1k\\text{. Find }\\sum_{n=1}^{\\infty}\\frac{(-1)^{n+1}H_n}{2^n}"},
    "refine-series-057": {"prompt":"H_n=\\sum_{k=1}^{n}\\frac1k\\text{. Find }\\sum_{n=1}^{\\infty}\\frac{H_{2n}}{4^n}"},
    "refine-series-058": {"prompt":"H_n=\\sum_{k=1}^{n}\\frac1k\\text{. Find }\\sum_{n=1}^{\\infty}\\frac{H_n}{n(n+1)(n+2)}"},
    "refine-series-059": {"prompt":"\\text{Expand }f(x)=x\\ (-\\pi<x<\\pi)\\text{ as the Fourier series }\\sum_{n=1}^{\\infty}b_n\\sin(nx)\\,\\text{. Find }b_3"},
    "refine-series-060": {"prompt":"\\text{The Fourier series of }f(x)=|x|\\ (-\\pi\\le x\\le\\pi)\\text{ is }\\frac{\\pi}{2}-\\frac{4}{\\pi}\\sum_{k=1}^{\\infty}\\frac{\\cos(2k-1)x}{(2k-1)^2}\\text{. Use it to find }\\sum_{k=1}^{\\infty}\\frac{1}{(2k-1)^2}"},
    "refine-series-061": {"prompt":"\\text{Using the Fourier series of }\\cosh x\\text{ on }[-\\pi,\\pi]\\text{, find }\\sum_{n=1}^{\\infty}\\frac{(-1)^{n+1}}{n^2+1}"},
    "refine-series-062": {"prompt":"\\text{Find }\\sum_{n=1}^{\\infty}\\frac{1}{(n^2+1)^2}"},
