    "refine-series-064": {"prompt":"f_n(x)=\\frac{x^n}{1+x^n}\\text{ converges pointwise on }[0,2]\\text{ to }f(x)\\text{. Find }\\int_0^2 f(x)\\,dx"},
    "refine-series-065": {"prompt":"f_n(x)=nx(1-x^2)^n\\text{ converges pointwise on }[0,1]\\text{ to }0\\text{. Find }\\lim_{n\\to\\infty}\\int_0^1 f_n(x)\\,dx"},
