    "refine-series-067": {"prompt":"g(x)=\\sum_{n=1}^{\\infty}\\frac{\\sin(nx)}{n^3}\\text{. Find }g'\\!\\left(\\frac{\\pi}{3}\\right)"},
    "refine-series-068": {"prompt":"\\text{Theorem: }a_n\\text{ positive, decreasing, and }\\sum a_n\\text{ convergent}\\Rightarrow n\\,a_n\\to0\\text{. Drop the word decreasing and look at a counterexample: }a_n=\\frac1n\\ (n\\text{ a perfect square})\\text{, otherwise }a_n=\\frac{1}{n^2}\\text{. }\\sum a_n\\text{ converges; find }\\limsup_{n\\to\\infty}n\\,a_n"},
    "refine-series-069": {"prompt":"\\text{Let }a_n=\\frac{\\cos(2n\\pi/3)}{\\sqrt[3]{n}}\\text{: }\\sum a_n\\text{ converges, but }\\sum a_n^3\\text{ diverges. Find }\\lim_{N\\to\\infty}\\left(\\sum_{n=1}^{3N}a_n^3-\\frac14\\sum_{n=1}^{3N}\\frac1n\\right)"},
    "refine-series-070": {"prompt":"\\text{The series }1-1+1-1+\\cdots\\text{ diverges. Find its Cesaro sum }\\lim_{N\\to\\infty}\\frac{S_1+S_2+\\cdots+S_N}{N}\\text{ (}S_k\\text{ is the partial sum)}"},
    "refine-series-071": {"prompt":"\\text{Find the Cesaro sum of }\\sum_{n=1}^{\\infty}\\cos\\frac{2n\\pi}{3}\\text{ (the limit of the averages of the partial sums)}"},
    "refine-series-072": {"prompt":"\\text{Find the Cesaro sum of }\\sum_{n=1}^{\\infty}(-1)^{n+1}\\frac{n}{n+1}"},
    "refine-series-073": {"prompt":"H_n=\\sum_{k=1}^{n}\\frac1k\\text{. Find the Cesaro sum of }\\sum_{n=1}^{\\infty}(-1)^{n+1}H_n"},
    "refine-series-074": {"prompt":"\\text{Find the Abel sum of }1-2+3-4+\\cdots=\\sum_{n=0}^{\\infty}(-1)^n(n+1)\\text{, i.e. }\\lim_{x\\to1^-}\\sum_{n=0}^{\\infty}(-1)^n(n+1)x^n"},
    "refine-series-075": {"prompt":"\\text{Alternating sum of the triangular numbers: }1-3+6-10+\\cdots=\\sum_{n=0}^{\\infty}(-1)^n\\frac{(n+1)(n+2)}{2}\\text{. Find its Abel sum}"},
    "refine-series-076": {"prompt":"\\text{Find the Abel sum of }\\sum_{n=1}^{\\infty}n\\cos\\frac{2n\\pi}{3}\\text{, i.e. }\\lim_{x\\to1^-}\\sum_{n=1}^{\\infty}n\\cos\\frac{2n\\pi}{3}\\,x^n"},
    "refine-series-077": {"prompt":"\\text{Find the Abel sum of }\\sum_{n=1}^{\\infty}(-1)^{n+1}\\ln n=\\ln1-\\ln2+\\ln3-\\cdots"},
    "refine-series-078": {"prompt":"a_n=\\left(\\frac{2+(-1)^n}{5}\\right)^n\\text{. Find }\\limsup_{n\\to\\infty}\\sqrt[n]{a_n}"},
    "refine-series-079": {"prompt":"a_n=2^{-n+(-1)^n}\\text{. }\\sum a_n\\text{ converges (the root limit is }\\tfrac12\\text{), but the ratio test fails. Find }\\limsup_{n\\to\\infty}\\frac{a_{n+1}}{a_n}"},
